const STORE={get:k=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch{}},remove:k=>{try{localStorage.removeItem(k)}catch{}}};
const S={token:STORE.get('nexora_token'),user:null,page:'home',back:[],chat:null,direct:null,socket:null,theme:STORE.get('nexora_theme')||'light'};
const $=q=>document.querySelector(q),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const DEMO_KEY='nexora_demo_db';
function demoDB(){let d;try{d=JSON.parse(STORE.get(DEMO_KEY)||'null')}catch{d=null}if(!d)d={users:[{id:'demo-user',name:'NEXORA Demo',email:'demo@nexora.app',bio:'Discover • Connect • Grow',premium:false,avatar:'',followers:[],following:[],blocked:[],xp:0,streak:0,longestStreak:0,level:1}],posts:[],groups:[],messages:[],directMessages:[],opportunities:[],listings:[],events:[],stories:[],notifications:[],applications:[],checkins:[],aiChats:[],courses:[{id:'c1',title:'Digital Skills Starter',category:'Technology',level:'Beginner',progress:0},{id:'c2',title:'Entrepreneurship Essentials',category:'Business',level:'Beginner',progress:0},{id:'c3',title:'Career & CV Mastery',category:'Career',level:'All levels',progress:0},{id:'c4',title:'Personal Finance Basics',category:'Finance',level:'Beginner',progress:0}],settings:{notifications:true,private:false}};if(!d.checkins)d.checkins=[];if(!d.aiChats)d.aiChats=[];if(d.users[0]){if(d.users[0].xp===undefined)d.users[0].xp=0;if(d.users[0].streak===undefined)d.users[0].streak=0;if(d.users[0].longestStreak===undefined)d.users[0].longestStreak=0}return d}
function saveDemo(d){STORE.set(DEMO_KEY,JSON.stringify(d))} function demoUser(){return demoDB().users[0]}
function demoXpLevel(xp){return Math.floor((xp||0)/100)+1}
function demoBuildAIReply(d,user,rawMessage){
  const x=String(rawMessage||'').trim().toLowerCase();
  const suggestions=[];let answer=null;
  const greetRe=/^(hi|hello|hey|yo|sup|good (morning|afternoon|evening)|howdy)\b/;
  const thanksRe=/\b(thanks|thank you|thx|appreciate)\b/;
  const helpRe=/^(what can you do|help|help me|capabilities|features|who are you)\??$/;
  if(greetRe.test(x)){
    const streak=user.streak||0;
    answer=`👋 Hey ${String(user.name||'there').split(' ')[0]}! ${streak>0?`🔥 You're on a ${streak}-day streak — keep it going! `:''}What are you in the mood for — jobs, the marketplace, learning, or your feed?`;
    suggestions.push('Find work for me','Show trending posts','Check my streak');
  }else if(thanksRe.test(x)){
    answer='🙌 Anytime! I\'m always here to help you navigate NEXORA.';
  }else if(helpRe.test(x)){
    answer='✦ I\'m your NEXORA guide. I can help with jobs, the marketplace, learning, messages, premium, safety, your streak/XP and the leaderboard. Just ask naturally!';
    suggestions.push('Find work for me','How do I sell something?','Show leaderboard');
  }else if(/streak|check.?in|\bxp\b|\blevel\b|\bpoints\b|\bbadge\b/.test(x)){
    const streak=user.streak||0,xp=user.xp||0,level=demoXpLevel(xp);
    const today=new Date().toISOString().slice(0,10);
    const checkedInToday=(d.checkins||[]).some(c=>c.date===today);
    answer=`🔥 Streak: ${streak} day${streak===1?'':'s'}\n⭐ Level ${level} (${xp} XP)\n${checkedInToday?'You already checked in today — nice! ✅':'You haven\'t checked in today yet — do that to keep your streak alive.'}`;
    suggestions.push(checkedInToday?'Show leaderboard':'Daily check-in');
  }else if(/leaderboard|\brank\b|top user|who.?s winning/.test(x)){
    answer=`🏆 In Preview mode the leaderboard only tracks you: ${user.xp||0} XP, Level ${demoXpLevel(user.xp||0)}. Connect the live backend to see how you rank against everyone else!`;
    suggestions.push('Daily check-in');
  }else if(/communit(y|ies)|\bgroup\b/.test(x)){
    answer=`👥 There are ${(d.groups||[]).length} communities saved locally. Join or start one that matches your interests.`;
    suggestions.push('Open Communities');
  }else if(/\bevent\b|\brsvp\b|meetup/.test(x)){
    const upcoming=(d.events||[]).length;
    answer=`📅 There ${upcoming===1?'is':'are'} ${upcoming} event${upcoming===1?'':'s'} saved locally. Open Events to RSVP or host your own.`;
    suggestions.push('Open Events');
  }else if(/\bpremium\b|\bpayment\b|mpesa|subscri/.test(x)){
    answer=user.premium?'💎 You\'re already Premium — thank you!':'💳 NEXORA Premium is KSh 100/month via M-Pesa STK Push. In Preview mode payments are simulated — connect the live backend for real M-Pesa.';
    suggestions.push('Open Wallet');
  }else if(/\bsafe\b|\breport\b|\bblock\b|security|password|2fa/.test(x)){
    answer='🛡️ Your safety matters. Use Safety to report content or block someone, and Settings → Security to manage your password and sessions.';
    suggestions.push('Open Safety','Open Settings');
  }else if(/\bmessag|\bchat\b|\bcall\b|\bdm\b|conversation/.test(x)){
    const count=(d.directMessages||[]).length;
    answer=count?`✉️ You have ${count} message${count===1?'':'s'} saved locally. Open Messages to catch up.`:'✉️ Your inbox is empty right now — open Messages to start a conversation.';
    suggestions.push('Open Messages');
  }else if(/\bprofile|\bbio\b|\bavatar\b|edit my/.test(x)){
    answer='👤 Open Profile to update your photo, bio, skills and work history. A complete profile gets more attention!';
    suggestions.push('Open Profile');
  }else if(/\btrend|\bpopular|\bexplore|what.?s (new|happening)/.test(x)){
    const trending=(d.posts||[]).slice().sort((a,b)=>(b.likesCount||0)-(a.likesCount||0)).slice(0,3);
    answer=trending.length?`📈 Trending locally:\n${trending.map(p=>`• "${(p.text||'[media]').slice(0,60)}" — ${p.likesCount||0} likes`).join('\n')}`:'📈 Nothing trending yet — be the first to post!';
    suggestions.push('Open Explore');
  }else if(/stud(y|ies)|\bcourse|education|\blearn|\bskill/.test(x)){
    const started=(d.courses||[]).filter(c=>(c.progress||0)>0);
    answer=started.length?`🎓 You've made progress on ${started.length} course${started.length===1?'':'s'}. Keep chipping away — every lesson counts!`:'🎓 Open Education to start a course — Digital Skills, Entrepreneurship, Career & CV Mastery, or Personal Finance.';
    suggestions.push('Open Education');
  }else if(/\bmarket|\bsell|\bbuy\b|\bproduct|\bshop|\blisting/.test(x)){
    const listings=(d.listings||[]).slice(0,3);
    answer=`🛒 The Marketplace has ${(d.listings||[]).length} listing${(d.listings||[]).length===1?'':'s'} saved locally.${listings.length?`\n\n${listings.map(l=>`• ${l.title} — KSh ${l.price}`).join('\n')}`:''}\n\nOpen Marketplace to buy or sell.`;
    suggestions.push('Open Marketplace','Create a listing');
  }else if(/\bjob\b|\bwork\b|\bcareer|\bintern|\bhire|\bfreelance|\bgig/.test(x)){
    const open=(d.opportunities||[]).slice(0,3);
    answer=`💼 There ${((d.opportunities||[]).length===1)?'is':'are'} ${(d.opportunities||[]).length} opportunit${(d.opportunities||[]).length===1?'y':'ies'} saved locally.${open.length?`\n\n${open.map(o=>`• ${o.title}`).join('\n')}`:''}\n\nOpen Opportunities to apply.`;
    suggestions.push('Open Opportunities','Post an opportunity');
  }else{
    answer='✦ I can help with jobs, the marketplace, education, messages, premium, safety, communities, events, your profile, or your streak/XP. What would you like to do?';
    suggestions.push('Find work for me','Show trending posts','Check my streak');
  }
  return{answer,suggestions};
}
