 m=url.match(/^\/api\/posts\/([^/]+)$/);if(m&&method==='PATCH'){const p=d.posts.find(x=>x.id===m[1]);if(!p)throw Error('Post not found');let b={};try{b=JSON.parse(body||'{}')}catch{}p.text=String(b.text||'').slice(0,5000);p.updatedAt=new Date().toISOString();saveDemo(d);return{ok:true}}if(m&&method==='DELETE'){const i=d.posts.findIndex(x=>x.id===m[1]);if(i<0)throw Error('Post not found');d.posts.splice(i,1);saveDemo(d);return{ok:true}};
 if(url==='/api/groups'&&method==='GET')return{groups:d.groups};if(url==='/api/groups'&&method==='POST'){let b={};try{b=JSON.parse(body||'{}')}catch{}const g={id:'g-'+Date.now(),name:String(b.name||'New Community').slice(0,100),description:String(b.description||'').slice(0,500),category:b.category||'General',members:[demoUser().id],joined:true};d.groups.unshift(g);saveDemo(d);return{group:g}};
 m=url.match(/^\/api\/groups\/([^/]+)\/join$/);if(m){const g=d.groups.find(x=>x.id===m[1]);if(!g)throw Error('Community not found');g.members=g.members||[];const j=g.members.includes(demoUser().id);g.members=j?g.members.filter(x=>x!==demoUser().id):g.members.concat(demoUser().id);g.joined=!j;g.membersCount=g.members.length;saveDemo(d);return{joined:!j,membersCount:g.members.length}};
 m=url.match(/^\/api\/groups\/([^/]+)\/messages$/);if(m&&method==='GET')return{messages:d.messages.filter(x=>x.groupId===m[1])};
