 if(url.startsWith('/api/search')){const q=(new URLSearchParams(url.split('?')[1]||'').get('q')||'').toLowerCase();return{users:d.users.filter(x=>x.id!==demoUser().id&&x.name.toLowerCase().includes(q)),groups:d.groups.filter(x=>x.name.toLowerCase().includes(q)),opportunities:d.opportunities.filter(x=>x.title.toLowerCase().includes(q)),listings:d.listings.filter(x=>x.title.toLowerCase().includes(q)),events:d.events.filter(x=>x.title.toLowerCase().includes(q))}};
 m=url.match(/^\/api\/users\/([^/]+)\/follow$/);if(m){const u=d.users.find(x=>x.id===m[1]);if(!u)throw Error('User not found');u.followers=u.followers||[];const on=(d.users[0].following||[]).includes(u.id);d.users[0].following=on?d.users[0].following.filter(x=>x!==u.id):[...(d.users[0].following||[]),u.id];u.followers=on?u.followers.filter(x=>x!==d.users[0].id):[...u.followers,d.users[0].id];saveDemo(d);return{following:!on}};
 if(url==='/api/notifications')return{notifications:d.notifications||[]};if(url==='/api/notifications/read'){(d.notifications||[]).forEach(n=>n.read=true);saveDemo(d);return{ok:true}};
 if(url==='/api/opportunities'&&method==='GET')return{items:d.opportunities};if(url==='/api/opportunities'&&method==='POST'){let b={};try{b=JSON.parse(body||'{}')}catch{}const o={id:'opp-'+Date.now(),title:b.title||'New opportunity',description:b.description||'',category:b.category||'General',type:b.type||'Job',location:b.location||'',remote:!!b.remote,deadline:b.deadline||'',ownerId:demoUser().id,createdAt:new Date().toISOString()};d.opportunities.unshift(o);saveDemo(d);return{item:o}};
