 if(url==='/api/stories'&&method==='GET')return{stories:d.stories};if(url==='/api/stories'&&method==='POST'){let text='';if(body instanceof FormData)text=body.get('text')||'';const s={id:'st-'+Date.now(),text,author:demoUser(),createdAt:new Date().toISOString(),expiresAt:new Date(Date.now()+86400000).toISOString(),files:[]};d.stories.unshift(s);saveDemo(d);return{story:s}};
 if(url==='/api/education')return{courses:d.courses};m=url.match(/^\/api\/education\/([^/]+)\/progress$/);if(m&&method==='POST'){const c=d.courses.find(x=>x.id===m[1]);if(!c)throw Error('Course not found');c.progress=Math.min(100,(c.progress||0)+25);saveDemo(d);return{course:c}};
 if(url==='/api/saved')return{posts:d.posts.filter(x=>x.saved)};if(url==='/api/premium/status')return{premium:!!demoUser().premium};if(url==='/api/payments/mpesa/stk')return{ok:true,demo:true};
 if(url.startsWith('/api/messages/')&&method==='GET')return{messages:d.directMessages.filter(m=>m.fromId===demoUser().id||m.toId===demoUser().id)};if(url.startsWith('/api/messages/')&&method==='POST'){let b={};try{b=JSON.parse(body||'{}')}catch{}const uid=url.split('/').pop(),msg={id:'dm-'+Date.now(),fromId:demoUser().id,toId:uid,text:b.text||'',createdAt:new Date().toISOString(),user:demoUser()};d.directMessages.push(msg);saveDemo(d);return{message:msg}};
 if(url==='/api/settings'&&method==='GET')return{settings:d.settings};if(url==='/api/settings'&&method==='PATCH'){let b={};try{b=JSON.parse(body||'{}')}catch{}d.settings={...d.settings,...b};saveDemo(d);return{settings:d.settings}};if(url==='/api/applications')return{applications:d.applications||[]};if(url==='/api/payments/history')return{payments:d.payments||[]};if(url.startsWith('/api/block/')){const uid=url.split('/').pop();d.users[0].blocked=d.users[0].blocked||[];const on=d.users[0].blocked.includes(uid);d.users[0].blocked=on?d.users[0].blocked.filter(x=>x!==uid):[...d.users[0].blocked,uid];saveDemo(d);return{blocked:!on}};if(url==='/api/export')return d;
 if(url==='/api/report'){d.notifications=d.notifications||[];d.notifications.unshift({id:'r-'+Date.now(),type:'report',text:'Your report has been received.',read:false,createdAt:new Date().toISOString()});saveDemo(d);return{ok:true,message:'Thanks. Your report has been recorded.'}};
