 if(url.includes('/comments/')&&url.endsWith('/delete')){const bits=url.split('/');const pid=bits[3],cid=bits[5],p=d.posts.find(x=>x.id===pid);if(p)p.comments=(p.comments||[]).filter(c=>c.id!==cid);saveDemo(d);return{ok:true}};
