 if(url==='/api/checkin'&&method==='POST'){const user=d.users[0],today=new Date().toISOString().slice(0,10);const already=(d.checkins||[]).some(c=>c.date===today);if(already){return{ok:true,alreadyCheckedIn:true,streak:user.streak||0,longestStreak:user.longestStreak||0,xp:user.xp||0,level:demoXpLevel(user.xp||0)}}const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);const hadYesterday=(d.checkins||[]).some(c=>c.date===yesterday);user.streak=hadYesterday?(user.streak||0)+1:1;user.longestStreak=Math.max(user.longestStreak||0,user.streak);const gain=10+Math.min(user.streak,10)*2;const before=demoXpLevel(user.xp||0);user.xp=(user.xp||0)+gain;const level=demoXpLevel(user.xp);d.checkins=d.checkins||[];d.checkins.push({id:'chk-'+Date.now(),date:today,createdAt:new Date().toISOString()});saveDemo(d);return{ok:true,alreadyCheckedIn:false,streak:user.streak,longestStreak:user.longestStreak,xp:user.xp,xpGained:gain,level,leveledUp:level>before}};
