async function home(){shell('Home',`<div class="hero"><div><span class="pill">WELCOME BACK</span><h2>${esc(S.user.name)}, discover what's next.</h2><p>Your all-in-one space to connect, learn, work, buy, sell and grow.</p><div class="actions"><button class="btn" onclick="composer()">＋ Create post</button><button class="btn secondary" onclick="nav('explore')">Explore people</button></div></div><div class="heroStats"><b>Everything in one app</b><span>Social · Work · Business · Community</span><div id="homeStreak" class="streakStrip">…</div></div></div><div class="quickGrid"><button class="quick" onclick="nav('opportunities')">💼 Find work</button><button class="quick" onclick="nav('marketplace')">🛒 Shop</button><button class="quick" onclick="nav('communities')">👥 Join community</button><button class="quick" onclick="nav('events')">📅 Find events</button></div><div class="grid4">${card('Social Feed','Posts, photos, videos and documents.')} ${card('Opportunities','Jobs, gigs, internships and services.')} ${card('Marketplace','Products and services from members.')} ${card('Communities','Groups, chat, events and learning.')}</div><div id="feed"><div class="empty">Loading feed…</div></div>`);try{const d=await api('/api/posts');$('#feed').innerHTML=(d.posts||[]).map(post).join('')||card('Your feed is ready','Be the first to share something with the NEXORA community.')}catch(e){toast(e.message)}loadHomeStreak()}
