function open(html){$('#modal').className='modal';$('#modal').innerHTML=`<div class="sheet">${html}<button class="close" onclick="closeM()">Close</button></div>`}function closeM(){$('#modal').className='modal hidden';$('#modal').innerHTML=''}
let pc=null,stream=null;
async function incomingCall({from,fromName,offer}){if(!S.socket)return;const accept=confirm(`${fromName||'A NEXORA member'} is calling you. Accept video call?`);if(!accept){S.socket.emit('call:end',{to:from});return}try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.onicecandidate=e=>e.candidate&&S.socket.emit('call:ice',{to:from,candidate:e.candidate});pc.ontrack=e=>{const r=$('#remote');if(r)r.srcObject=e.streams[0]};open(`<h3>Call with ${esc(fromName||'NEXORA member')}</h3><video id="remote" class="callvideo" autoplay playsinline></video><button class="btn danger" onclick="endCall('${from}')">End call</button>`);await pc.setRemoteDescription(offer);const a=await pc.createAnswer();await pc.setLocalDescription(a);S.socket.emit('call:answer',{to:from,answer:a})}catch{toast('Camera/microphone permission is required')}}
async function startCall(to,name){if(!S.socket||window.NEXORA_DEMO)return toast('Video calls require the live backend and a secure browser context.');try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.onicecandidate=e=>e.candidate&&S.socket.emit('call:ice',{to,candidate:e.candidate});pc.ontrack=e=>{const r=$('#remote');if(r)r.srcObject=e.streams[0]};open(`<h3>Calling ${esc(name)}</h3><video id="remote" class="callvideo" autoplay playsinline></video><button class="btn danger" onclick="endCall('${to}')">End call</button>`);const o=await pc.createOffer();await pc.setLocalDescription(o);S.socket.emit('call:offer',{to,offer:o})}catch{toast('Camera/microphone permission is required')}}
function endCall(to){S.socket?.emit('call:end',{to});pc?.close();stream?.getTracks().forEach(t=>t.stop());closeM()}
(async()=>{if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.getRegistrations().then(rs=>Promise.all(rs.map(r=>r.unregister()))).finally(()=>navigator.serviceWorker.register('./sw-v11.js').catch(()=>{}));}if(S.token){try{S.user=(await api('/api/me')).user;connect()}catch{S.token=null;STORE.remove('nexora_token')}}render();updateMode()})();


/* NEXORA V8 — production-oriented UX, security, moderation and account controls. */
function safeDate(v){const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toLocaleString()}
function metric(label,value){return `<div class="card statCard"><small>${esc(label)}</small><h2>${Number(value||0).toLocaleString()}</h2></div>`}
async function dashboard(){shell('My Dashboard',`<div id="dashStats" class="grid4"><div class="empty">Loading your dashboard…</div></div><div class="grid2"><div class="card"><h3>Quick actions</h3><div class="actions"><button class="btn" onclick="composer()">＋ Create post</button><button class="btn" onclick="createOpportunity()">＋ Post opportunity</button><button class="btn" onclick="createListing()">＋ Sell something</button><button class="btn" onclick="createEvent()">＋ Create event</button></div></div><div class="card"><h3>Account health</h3><p>Keep your profile complete, use a strong password and review privacy settings regularly.</p><button class="btn secondary" onclick="nav('settings')">Account settings</button></div></div>`);try{const d=await api('/api/dashboard');const x=d.stats||{};$('#dashStats').innerHTML=[['Posts',x.posts],['Followers',x.followers],['Following',x.following],['Listings',x.listings],['Opportunities',x.opportunities],['Events',x.events],['Applications',x.applications],['Messages',x.messages]].map(a=>metric(a[0],a[1])).join('')}catch(e){toast(e.message)}}
async function profile(){shell('Profile',`<div class="profileCard"><div class="profileTop"><div class="bigAvatar">${S.user.avatar?`<img src="${esc(S.user.avatar)}">`:esc((S.user.name||'U')[0])}</div><div><h2>${esc(S.user.name)}</h2><p>${esc(S.user.email)}</p>${S.user.premium?'<span class="verified">✓ Premium</span>':''}${S.user.admin?'<span class="verified">✓ Admin</span>':''}</div></div><div id="profileStats" class="grid4"></div><label>Profile photo<input id="av" class="input" type="file" accept="image/*"></label><input id="pn" class="input" value="${esc(S.user.name)}" maxlength="80" placeholder="Name"><textarea id="pb" class="textarea" maxlength="500" placeholder="Bio">${esc(S.user.bio||'')}</textarea><input id="ps" class="input" placeholder="Skills (comma separated)" value="${esc((S.user.skills||[]).join(', '))}"><input id="pe" class="input" placeholder="Education" value="${esc(S.user.education||'')}"><input id="pw" class="input" placeholder="Work / profession" value="${esc(S.user.work||'')}"><input id="pweb" class="input" placeholder="Website / portfolio" value="${esc(S.user.website||'')}"><div class="actions"><button class="btn" onclick="saveProfile()">Save profile</button><button class="btn secondary" onclick="exportData()">Export my data</button><button class="btn secondary" onclick="nav('settings')">Security & settings</button><button class="btn secondary" onclick="nav('ai')">Ask NEXORA AI</button></div></div>`);try{const d=await api('/api/dashboard');$('#profileStats').innerHTML=[['Posts',d.stats.posts],['Followers',d.stats.followers],['Following',d.stats.following],['Listings',d.stats.listings]].map(a=>metric(a[0],a[1])).join('')}catch{}}
async function viewProfile(id){try{const d=await api('/api/users/'+encodeURIComponent(id));const u=d.user;open(`<div class="profileCard"><div class="profileTop"><div class="bigAvatar">${u.avatar?`<img src="${esc(u.avatar)}">`:esc((u.name||'U')[0])}</div><div><h2>${esc(u.name)}</h2><p>${esc(u.bio||'NEXORA member')}</p>${u.premium?'<span class="verified">✓ Premium</span>':''}</div></div><div class="grid2"><div class="card"><b>${u.followers}</b><small> Followers</small></div><div class="card"><b>${u.following}</b><small> Following</small></div></div><div class="actions"><button class="btn" onclick="follow('${u.id}');closeM()">${u.following?'Unfollow':'Follow'}</button><button class="btn secondary" onclick="closeM();openDirect('${u.id}',decodeURIComponent('${encodeURIComponent(u.name)}'))">Message</button><button class="btn secondary" onclick="blockUser('${u.id}');closeM()">Block</button></div></div>`)}catch(e){toast(e.message)}}
async function settings(){shell('Settings & Security',`<div class="grid2"><div class="card"><h3>Appearance</h3><p>Choose light or dark mode.</p><button class="btn" onclick="toggleTheme()">Switch to ${S.theme==='light'?'dark':'light'} mode</button></div><div class="card"><h3>Notifications</h3><label><input id="setNotify" type="checkbox" checked> In-app notifications</label><button class="btn" onclick="saveSettings()">Save notification settings</button></div><div class="card"><h3>Privacy</h3><label><input id="setPrivate" type="checkbox"> Make profile private</label><button class="btn" onclick="saveSettings()">Save privacy</button></div><div class="card"><h3>Security center</h3><p>Verification, 2FA preference, active sessions and login activity.</p><button class="btn secondary" onclick="securityCenter()">Open security center</button></div><div class="card"><h3>Change password</h3><input id="oldPass" class="input" type="password" placeholder="Current password"><input id="newPass" class="input" type="password" minlength="8" placeholder="New password (8+ characters)"><button class="btn" onclick="changePassword()">Change password</button></div><div class="card"><h3>Account</h3><button class="btn secondary" onclick="exportData()">Export my data</button><button class="btn danger" onclick="confirmDeleteAccount()">Delete my account</button><button class="btn secondary" onclick="logout()">Log out</button></div><div class="card"><h3>App status</h3><p>Version 10.0 • ${window.NEXORA_DEMO?'Preview mode':'Backend connected'}</p><p class="muted">Live production mode should use HTTPS, a strong JWT secret, a persistent database and object storage.</p></div></div>`);api('/api/settings').then(d=>{if($('#setNotify'))$('#setNotify').checked=d.settings?.notifications!==false;if($('#setPrivate'))$('#setPrivate').checked=!!d.settings?.private}).catch(()=>{})}
async function changePassword(){const current=$('#oldPass')?.value||'',next=$('#newPass')?.value||'';if(next.length<8)return toast('New password must be at least 8 characters');try{const d=await api('/api/me/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:current,newPassword:next})});toast(d.message||'Password changed');$('#oldPass').value='';$('#newPass').value=''}catch(e){toast(e.message)}}
function confirmDeleteAccount(){open(`<h3>Delete account</h3><p>This permanently removes your account and your NEXORA content. This cannot be undone.</p><input id="deletePass" class="input" type="password" placeholder="Enter your password to confirm"><button class="btn danger" onclick="deleteAccount()">Permanently delete</button>`)}
async function deleteAccount(){try{await api('/api/me',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#deletePass').value})});closeM();logout()}catch(e){toast(e.message)}}
async function notifications(){shell('Notifications',`<div class="between"><p class="muted">Your recent activity and account alerts.</p><button class="btn secondary" onclick="markNotifications()">Mark all read</button></div><div id="noticeList"></div>`);try{const d=await api('/api/notifications');const a=d.notifications||[];$('#noticeList').innerHTML=a.map(n=>card(esc(n.type||'Notification'),`<p>${esc(n.text||'')}</p><small>${safeDate(n.createdAt)} ${n.read?'• read':'• unread'}</small><div class="actions">${!n.read?`<button class="btn secondary" onclick="markOne('${n.id}')">Mark read</button>`:''}<button class="btn danger" onclick="deleteNotice('${n.id}')">Delete</button></div>`)).join('')||'<div class="empty">No notifications.</div>'}catch(e){toast(e.message)}}
async function markOne(id){try{await api('/api/notifications/'+encodeURIComponent(id)+'/read',{method:'POST'});notifications()}catch(e){toast(e.message)}}
async function deleteNotice(id){try{await api('/api/notifications/'+encodeURIComponent(id),{method:'DELETE'});notifications()}catch(e){toast(e.message)}}
async function post(p){window.__nexoraPosts=window.__nexoraPosts||{};window.__nexoraPosts[p.id]=p.text||'';const fs=(p.files||[]).map(f=>f.type?.startsWith('image/')?`<img class="media" src="${esc(f.url)}" loading="lazy">`:f.type?.startsWith('video/')?`<video class="media" controls src="${esc(f.url)}"></video>`:`<a class="file" href="${esc(f.url)}" target="_blank" rel="noopener">📎 ${esc(f.name)}</a>`).join('');const mine=p.author?.id===S.user?.id;return`<article class="card post"><div class="between"><button class="author profileLink" onclick="viewProfile('${p.author?.id||''}')"><div class="avatar">${p.author?.avatar?`<img src="${esc(p.author.avatar)}">`:esc((p.author?.name||'U')[0])}</div><div><b>${esc(p.author?.name||'User')}</b>${p.author?.premium?' <span class="verified">✓ Premium</span>':''}<small>${safeDate(p.createdAt)}${p.updatedAt?' • edited':''}</small></div></button>${mine?`<div class="actions"><button class="iconBtn" onclick="editPost('${p.id}')">✏️</button><button class="iconBtn" onclick="deletePost('${p.id}')">🗑️</button></div>`:''}</div><p>${esc(p.text).replace(/\n/g,'<br>')}</p>${fs}<div class="actions"><button class="btn secondary ${p.liked?'active':''}" onclick="like('${p.id}')">♥ ${p.likesCount||0}</button><button class="btn secondary" onclick="comment('${p.id}')">💬 ${(p.comments||[]).length}</button><button class="btn secondary" onclick="share('${p.id}')">↗ ${p.shares||0}</button><button class="btn secondary" onclick="savePost('${p.id}')">🔖 ${p.saved?'Saved':'Save'}</button></div>${(p.comments||[]).slice(-5).map(c=>`<div class="comment"><b>${esc(c.user?.name||'User')}</b> ${esc(c.text)} ${c.user?.id===S.user?.id||mine?`<button class="link" onclick="deleteComment('${p.id}','${c.id}')">Delete</button>`:''}</div>`).join('')}</article>`}
async function deleteComment(postId,commentId){try{await api(`/api/posts/${encodeURIComponent(postId)}/comments/${encodeURIComponent(commentId)}/delete`,{method:'POST'});home();toast('Comment deleted')}catch(e){toast(e.message)}}
async function explore(){shell('Explore',`<div class="searchRow"><input id="sq" class="input" placeholder="Search people, groups, jobs, products, events…" onkeydown="if(event.key==='Enter')doSearch()"><button class="btn" onclick="doSearch()">Search</button></div><div class="card"><small class="muted">Tip: search a name, job title, product, event or community.</small></div><div id="results"></div>`)}
async function doSearch(){try{const d=await api('/api/search?q='+encodeURIComponent($('#sq').value));$('#results').innerHTML=`<h3>People</h3><div class="grid2">${(d.users||[]).map(u=>`<div class="card"><div class="author"><div class="avatar">${u.avatar?`<img src="${esc(u.avatar)}">`:esc((u.name||'U')[0])}</div><div><b>${esc(u.name)}</b><small>${esc(u.bio||'NEXORA member')}</small></div></div><div class="actions"><button class="btn" onclick="viewProfile('${u.id}')">View</button><button class="btn secondary" onclick="follow('${u.id}')">${u.following?'Unfollow':'Follow'}</button><button class="btn secondary" onclick="openDirect('${u.id}',decodeURIComponent('${encodeURIComponent(u.name)}'))">Message</button><button class="btn secondary" onclick="blockUser('${u.id}')">Block</button></div></div>`).join('')||'<div class="empty">No people found.</div>'}</div><h3>Opportunities</h3><div class="grid2">${(d.opportunities||[]).map(o=>card(esc(o.title),`<p>${esc(o.description||'')}</p><small>${esc(o.category||'General')} • ${esc(o.type||'Job')}</small><div class="actions"><button class="btn" onclick="applyOpp('${o.id}')">Apply</button></div>`)).join('')||'<div class="empty">No opportunities found.</div>'}</div><h3>Marketplace</h3><div class="grid2">${(d.listings||[]).map(l=>card(esc(l.title),`<p>${esc(l.description||'')}</p><b>KSh ${Number(l.price||0).toLocaleString()}</b><div class="actions"><button class="btn" onclick="contactSeller('${l.sellerId||''}')">Contact seller</button></div>`)).join('')||'<div class="empty">No listings found.</div>'}</div><h3>Events</h3><div class="grid2">${(d.events||[]).map(e=>card(esc(e.title),`<p>${esc(e.location||'Online')}</p><small>${safeDate(e.date)}</small>`)).join('')||'<div class="empty">No events found.</div>'}</div>`}catch(e){toast(e.message)}}
async function messages(){shell('Messages',S.chat?`<div class="card"><div class="between"><h3>${esc(S.chat.name)}</h3><button class="btn secondary" onclick="toast('Group calls require a secure browser and live WebRTC backend')">📹 Call</button></div><div id="chatLog" class="chatLog"></div><div id="typing" class="muted"></div><div class="row"><input id="mi" class="input" placeholder="Write a message…" oninput="sendTyping(true)" onkeydown="if(event.key==='Enter')sendMsg()"><button class="btn" onclick="sendMsg()">Send</button></div></div>`:S.direct?`<div class="card"><div class="between"><h3>${esc(S.direct.name)}</h3><button class="btn secondary" onclick="startCall(S.direct.id,S.direct.name)">📹 Video call</button></div><div id="chatLog" class="chatLog"></div><div id="typing" class="muted"></div><div class="row"><input id="mi" class="input" placeholder="Write a message…" oninput="sendTyping(true)" onkeydown="if(event.key==='Enter')sendDirect()"><button class="btn" onclick="sendDirect()">Send</button></div></div>`:`<div><div class="card"><h3>Your conversations</h3><div id="conversations">Loading…</div></div><button class="btn" onclick="nav('explore')">Find people</button></div>`);if(!S.chat&&!S.direct){try{const d=await api('/api/conversations');$('#conversations').innerHTML=(d.conversations||[]).map(c=>`<button class="card conversation" onclick="openDirect('${c.user.id}',decodeURIComponent('${encodeURIComponent(c.user.name)}'))"><div class="author"><div class="avatar">${c.user.avatar?`<img src="${esc(c.user.avatar)}">`:esc((c.user.name||'U')[0])}</div><div><b>${esc(c.user.name)}</b><small>${esc(c.lastMessage?.text||'No messages')}</small></div><span>${c.unread?c.unread+' unread':''}</span></div></button>`).join('')||'<div class="empty">No conversations yet.</div>'}catch(e){toast(e.message)}return}if(S.chat){try{const d=await api(`/api/groups/${S.chat.id}/messages`);$('#chatLog').innerHTML=(d.messages||[]).map(m=>`<div class="msg"><b>${esc(m.user?.name||'User')}</b><p>${esc(m.text)}</p><small>${safeDate(m.createdAt)}</small></div>`).join('')||'<div class="empty">No messages yet.</div>';S.socket?.emit('group:join',S.chat.id)}catch(e){toast(e.message)}}if(S.direct){try{const d=await api(`/api/messages/${S.direct.id}`);$('#chatLog').innerHTML=(d.messages||[]).map(m=>`<div class="msg ${m.fromId===S.user.id?'mine':''}"><b>${esc(m.user?.name||'User')}</b><p>${esc(m.text)}</p><small>${safeDate(m.createdAt)}</small></div>`).join('')||'<div class="empty">No messages yet.</div>';api(`/api/messages/${S.direct.id}/read`,{method:'POST'}).catch(()=>{})}catch(e){toast(e.message)}}}
async function sendMsg(){const text=$('#mi')?.value.trim();if(!text||!S.chat)return;try{if(S.socket&&!window.NEXORA_DEMO&&S.socket.connected)S.socket.emit('group:message',{groupId:S.chat.id,text});else await api(`/api/groups/${S.chat.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});$('#mi').value='';if(!S.socket||window.NEXORA_DEMO)messages()}catch(e){toast(e.message)}}
async function marketplace(){shell('Marketplace',`<div class="between"><p class="muted">Buy, sell and discover products and services.</p><button class="btn" onclick="createListing()">＋ Sell something</button></div><div class="searchRow"><input id="marketQ" class="input" placeholder="Search marketplace" oninput="loadListings()"><button class="btn secondary" onclick="loadListings()">Refresh</button></div><div id="listingList" class="grid3"></div>`);loadListings()}
async function loadListings(){try{const d=await api('/api/listings?q='+encodeURIComponent($('#marketQ')?.value||''));$('#listingList').innerHTML=(d.items||[]).map(l=>card(esc(l.title),`${l.images?.[0]?`<img class="media" src="${esc(l.images[0])}">`:''}<p>${esc(l.description||'')}</p><b>KSh ${Number(l.price||0).toLocaleString()}</b><p class="muted">${esc(l.location||'Kenya')}</p><div class="actions">${l.sellerId!==S.user?.id?`<button class="btn" onclick="placeOrder('${l.id}')">Buy now</button>`:''}<button class="btn secondary" onclick="contactSeller('${l.sellerId||''}')">Contact seller</button><button class="btn secondary" onclick="shareText('${esc(l.title)}')">Share</button>${l.sellerId===S.user?.id?`<button class="btn danger" onclick="deleteListing('${l.id}')">Delete</button>`:''}</div>`)).join('')||'<div class="empty">No listings yet.</div>'}catch(e){toast(e.message)}}
async function placeOrder(id){const qty=Number(prompt('Quantity','1')||1);if(!Number.isFinite(qty)||qty<1)return;try{await api('/api/listings/'+encodeURIComponent(id)+'/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({qty:Math.floor(qty)})});toast('Order placed');nav('orders')}catch(e){toast(e.message)}}
async function deleteListing(id){if(!confirm('Delete this listing?'))return;try{await api('/api/listings/'+encodeURIComponent(id),{method:'DELETE'});marketplace();toast('Listing deleted')}catch(e){toast(e.message)}}
async function opportunities(){shell('Opportunities',`<div class="between"><p class="muted">Jobs, freelance work, internships, services and business leads.</p><button class="btn" onclick="createOpportunity()">＋ Post opportunity</button></div><div class="tabs"><button class="tab" onclick="loadOpp('')">All</button><button class="tab" onclick="loadOpp('Job')">Jobs</button><button class="tab" onclick="loadOpp('Freelance')">Freelance</button><button class="tab" onclick="loadOpp('Internship')">Internships</button><button class="tab" onclick="loadOpp('Service')">Services</button><button class="tab" onclick="loadOpp('Business')">Business</button></div><div id="oppList" class="grid2"></div>`);loadOpp('')}
async function loadOpp(filter){try{const d=await api('/api/opportunities');const a=(d.items||[]).filter(o=>!filter||o.type===filter);$('#oppList').innerHTML=a.map(o=>card(esc(o.title),`<p>${esc(o.description||'')}</p><div class="meta">${esc(o.category||'General')} • ${esc(o.type||'Job')} ${o.remote?'• Remote':''}${o.location?' • '+esc(o.location):''}</div>${o.deadline?`<small>Deadline: ${esc(o.deadline)}</small>`:''}<div class="actions"><button class="btn" onclick="applyOpp('${o.id}')">Apply</button><button class="btn secondary" onclick="shareText('${esc(o.title)}')">Share</button>${o.ownerId===S.user?.id?`<button class="btn danger" onclick="deleteOpportunity('${o.id}')">Delete</button>`:''}</div>`)).join('')||'<div class="empty">No opportunities yet. Post the first one.</div>'}catch(e){toast(e.message)}}
async function deleteOpportunity(id){if(!confirm('Delete this opportunity?'))return;try{await api('/api/opportunities/'+encodeURIComponent(id),{method:'DELETE'});opportunities();toast('Opportunity deleted')}catch(e){toast(e.message)}}
async function events(){shell('Events',`<div class="between"><p class="muted">Meetups, workshops, webinars and community events.</p><button class="btn" onclick="createEvent()">＋ Create event</button></div><div id="eventList" class="grid2"></div>`);loadEvents()}
async function loadEvents(){try{const d=await api('/api/events');$('#eventList').innerHTML=(d.items||[]).map(e=>card(esc(e.title),`<p>${esc(e.description||'')}</p><b>${safeDate(e.date)}</b><p>${esc(e.location||'Online')}</p><small>${e.attendees?.length||0} going${e.capacity?' • capacity '+e.capacity:''}</small><div class="actions"><button class="btn" onclick="rsvp('${e.id}')">${e.attendees?.includes?.(S.user.id)?'Cancel RSVP':'RSVP'}</button><button class="btn secondary" onclick="shareText('${esc(e.title)}')">Share</button>${e.hostId===S.user?.id?`<button class="btn danger" onclick="deleteEvent('${e.id}')">Delete</button>`:''}</div>`)).join('')||'<div class="empty">No events yet.</div>'}catch(e){toast(e.message)}}
async function deleteEvent(id){if(!confirm('Delete this event?'))return;try{await api('/api/events/'+encodeURIComponent(id),{method:'DELETE'});events();toast('Event deleted')}catch(e){toast(e.message)}}
async function stories(){shell('Stories, Reels & Live',`<div class="card"><h3>Create a story</h3><input id="storyFile" class="input" type="file" accept="image/*,video/*"><textarea id="storyText" class="textarea" maxlength="500" placeholder="Add a caption"></textarea><button class="btn" onclick="createStory()">＋ Publish story</button><p class="muted">Stories expire after 24 hours.</p></div><div id="storyList" class="grid3"></div>`);loadStories()}
async function loadStories(){try{const d=await api('/api/stories');$('#storyList').innerHTML=(d.stories||[]).filter(s=>!s.expiresAt||new Date(s.expiresAt)>new Date()).map(s=>card(esc(s.author?.name||'Member'),`${s.files?.[0]?.type?.startsWith('video/')?`<video class="media" controls src="${esc(s.files[0].url)}"></video>`:s.files?.[0]?`<img class="media" src="${esc(s.files[0].url)}">`:''}<p>${esc(s.text||'')}</p><small>${safeDate(s.createdAt)}</small>${s.author?.id===S.user?.id?`<div class="actions"><button class="btn danger" onclick="deleteStory('${s.id}')">Delete</button></div>`:''}`)).join('')||'<div class="empty">No active stories yet.</div>'}catch(e){toast(e.message)}}
async function deleteStory(id){if(!confirm('Delete this story?'))return;try{await api('/api/stories/'+encodeURIComponent(id),{method:'DELETE'});stories();toast('Story deleted')}catch(e){toast(e.message)}}
async function admin(){if(!S.user?.admin)return shell('Admin Center','<div class="empty">Administrator access is required.</div>');shell('Admin Center',`<div id="adminStats" class="grid4"><div class="empty">Loading…</div></div><div class="grid2"><div class="card"><div class="between"><h3>Reports</h3><button class="btn secondary" onclick="loadAdminReports()">Refresh</button></div><div id="adminReports">Loading…</div></div><div class="card"><div class="between"><h3>Support tickets</h3><button class="btn secondary" onclick="loadAdminSupport()">Refresh</button></div><div id="adminSupport">Loading…</div></div></div><div class="card"><h3>Members</h3><div id="adminUsers">Loading…</div></div>`);try{const d=await api('/api/admin/stats');$('#adminStats').innerHTML=Object.entries(d.stats||{}).map(a=>metric(a[0],a[1])).join('');loadAdminReports();loadAdminSupport();loadAdminUsers()}catch(e){toast(e.message)}}
async function loadAdminReports(){try{const d=await api('/api/admin/reports');$('#adminReports').innerHTML=(d.reports||[]).map(r=>`<div class="row"><span><b>${esc(r.user?.name||'Member')}</b><br>${esc(r.reason)}</span><button class="btn" onclick="reviewReport('${r.id}')">Mark reviewed</button></div>`).join('')||'No reports.'}catch(e){toast(e.message)}}
async function reviewReport(id){try{await api('/api/admin/reports/'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'reviewed'})});loadAdminReports()}catch(e){toast(e.message)}}
async function loadAdminSupport(){try{const d=await api('/api/admin/support');$('#adminSupport').innerHTML=(d.tickets||[]).map(t=>`<div class="row"><span><b>${esc(t.subject)}</b><br>${esc(t.text)}</span><button class="btn" onclick="closeTicket('${t.id}')">Close</button></div>`).join('')||'No support tickets.'}catch(e){toast(e.message)}}
async function closeTicket(id){try{await api('/api/admin/support/'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'closed'})});loadAdminSupport()}catch(e){toast(e.message)}}
async function loadAdminUsers(){try{const d=await api('/api/admin/users');$('#adminUsers').innerHTML=(d.users||[]).map(u=>`<div class="row"><span><b>${esc(u.name)}</b><br>${esc(u.email)}</span><span>${u.premium?'Premium':'Free'}</span></div>`).join('')||'No members.'}catch(e){toast(e.message)}}

async function ai(){shell('NEXORA AI V13',`<div class="card aiWorkspace"><div class="aiTop"><div class="aiIdentity"><div class="aiAvatar"><span>✦</span><i></i></div><div><div class="eyebrow">NEXORA INTELLIGENCE</div><h2>What’s on your mind?</h2><p class="muted">Chat naturally. Ask questions, brainstorm, plan, decide, write, or just talk.</p></div></div><div class="aiStatus"><span id="aiStatusDot"></span><span id="aiStatusText">Ready</span></div></div><div class="aiToolbar"><div class="aiModes"><button class="aiMode active" onclick="setAIMode(this,'Companion')">💬 Companion</button><button class="aiMode" onclick="setAIMode(this,'Coach')">🎯 Coach</button><button class="aiMode" onclick="setAIMode(this,'Creator')">🎨 Creator</button><button class="aiMode" onclick="setAIMode(this,'Planner')">🗓 Planner</button><button class="aiMode" onclick="setAIMode(this,'Tutor')">📚 Tutor</button></div><button class="tinyBtn" onclick="clearAIChat()" title="Clear conversation">＋ New chat</button></div><div id="aiLog" class="chatLog aiChatLog"></div><div id="aiChips" class="actions aiSuggestions"></div><div class="aiComposerWrap"><div class="aiComposer"><button class="iconBtn" title="Voice input" onclick="voiceInput()">🎙️</button><textarea id="aiInput" class="input aiTextarea" rows="1" maxlength="4000" placeholder="Message NEXORA…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();askAI()}"></textarea><button id="aiSend" class="aiSend" onclick="askAI()" title="Send">➤</button></div><div class="aiComposerMeta"><span>Enter to send · Shift+Enter for a new line</span><span id="aiModeLabel">Companion mode</span></div></div><div class="aiQuick"><button onclick="aiPrompt('I feel bored, talk to me')">💬 Talk with me</button><button onclick="aiPrompt('Help me decide what to do today')">🗓 Plan my day</button><button onclick="aiPrompt('Give me three practical ideas')">💡 Brainstorm</button><button onclick="aiPrompt('Help me find opportunities on NEXORA')">💼 Opportunities</button></div></div>`);loadAI();loadStreakBadge();checkAIStatus()}
let NEXORA_AI_MODE='Companion';
function setAIMode(btn,mode){NEXORA_AI_MODE=mode;document.querySelectorAll('.aiMode').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const l=$('#aiModeLabel');if(l)l.textContent=mode+' mode';}
function checkAIStatus(){const dot=$('#aiStatusDot'),txt=$('#aiStatusText');if(!dot||!txt)return;dot.dataset.state=window.NEXORA_DEMO?'offline':'online';txt.textContent=window.NEXORA_DEMO?'Preview AI':'AI ready'}
function voiceInput(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Voice input is not supported in this browser');return}const r=new SR();r.lang='en-US';r.interimResults=false;r.onstart=()=>toast('Listening…');r.onerror=()=>toast('Voice input could not start');r.onresult=e=>{const t=e.results?.[0]?.[0]?.transcript||'';if($('#aiInput')){$('#aiInput').value=t;askAI()}};r.start()}
function speakAI(text){if(!('speechSynthesis' in window)){toast('Voice playback is not supported here');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text).replace(/[•✦🤖]/g,''));u.rate=.98;window.speechSynthesis.speak(u)}
async function loadStreakBadge(){try{const d=await api('/api/checkin');const el=$('#streakBadge');if(!el)return;el.innerHTML=`<span class="pill gold">🔥 ${Number(d.streak)||0} day${Number(d.streak)===1?'':''}</span><span class="pill">⭐ Lvl ${Number(d.level)||1}</span>`+(d.checkedInToday?'<span class="muted" style="display:block;margin-top:6px;font-size:11px">Checked in today ✓</span>':'<button class="btn" style="margin-top:8px" onclick="doCheckin()">Daily check-in</button>')}catch(e){}}
async function doCheckin(){try{const d=await api('/api/checkin',{method:'POST'});if(d.alreadyCheckedIn){toast('Already checked in today');return}toast(`+${d.xpGained} XP · 🔥 ${d.streak}-day streak${d.leveledUp?' · 🎉 Level up!':''}`);if(d.leveledUp)celebrate();loadStreakBadge()}catch(e){toast(e.message)}}
function celebrate(){const c=document.createElement('div');c.className='confetti';document.body.appendChild(c);for(let i=0;i<24;i++){const s=document.createElement('span');s.style.left=Math.random()*100+'%';s.style.animationDelay=(Math.random()*0.4)+'s';s.style.background=['#3757ff','#a13cff','#ff4fc3','#ffd43b','#20d9ff'][i%5];c.appendChild(s)}setTimeout(()=>c.remove(),1800)}
function aiHistoryMarkup(messages){return (messages||[]).map(m=>`<div class="msg mine"><div class="msgHead"><b>You</b></div><p>${esc(String(m.message||'').replace(/^\[Mode: [^\]]+\] /,''))}</p></div><div class="msg aiMsg"><div class="msgHead"><b>✦ NEXORA</b><button class="tinyBtn" onclick="speakAI(this.closest('.msg').querySelector('p').innerText)" title="Speak">🔊</button></div><p>${esc(m.answer||'').replace(/\n/g,'<br>')}</p></div>`).join('')}
async function loadAI(){try{const d=await api('/api/ai/history');const log=$('#aiLog');if(!log)return;log.innerHTML=aiHistoryMarkup(d.messages)||`<div class="aiWelcome"><div class="aiWelcomeIcon">✦</div><h3>Hi${S.user?.name?`, ${esc(S.user.name.split(' ')[0])}`:''}.</h3><p>I'm NEXORA. We can talk about anything — from your day and decisions to work, ideas, money, relationships, learning and life.</p><div class="aiWelcomeExamples"><button onclick="aiPrompt('What can you help me with?')">What can you help me with?</button><button onclick="aiPrompt('Give me an interesting idea')">Give me an interesting idea</button><button onclick="aiPrompt('Let’s just talk')">Let’s just talk</button></div></div>`;log.scrollTop=log.scrollHeight;checkAIStatus()}catch(e){toast(e.message)}}
function aiPrompt(t){const el=$('#aiInput');if(!el)return;el.value=t;el.focus();askAI()}
async function clearAIChat(){if(!confirm('Start a new NEXORA conversation?'))return;try{if(window.NEXORA_DEMO){const d=demoDB();d.aiChats=[];saveDemo(d)}else await api('/api/ai/history',{method:'DELETE'});if($('#aiLog'))$('#aiLog').innerHTML='<div class="aiWelcome"><div class="aiWelcomeIcon">✦</div><h3>New conversation</h3><p>What would you like to talk about?</p></div>';if($('#aiChips'))$('#aiChips').innerHTML='';toast('New chat started')}catch(e){toast(e.message)}}
function addAIMessage(text,kind){const log=$('#aiLog');if(!log)return;const div=document.createElement('div');div.className='msg '+(kind==='user'?'mine':'aiMsg');div.innerHTML=kind==='user'?`<div class="msgHead"><b>You</b></div><p>${esc(text)}</p>`:`<div class="msgHead"><b>✦ NEXORA</b><button class="tinyBtn" onclick="speakAI(this.closest('.msg').querySelector('p').innerText)">🔊</button></div><p>${esc(text).replace(/\n/g,'<br>')}</p>`;log.appendChild(div);log.scrollTop=log.scrollHeight;return div}
const NEXORA_THINK_MIN_MS=2200;const NEXORA_THINK_MAX_MS=3400;function nexoraThinkDelay(){return NEXORA_THINK_MIN_MS+Math.floor(Math.random()*(NEXORA_THINK_MAX_MS-NEXORA_THINK_MIN_MS+1))}function nexoraThinkingMarkup(){return '<div class="msgHead thinkingHead"><div class="thinkingSticker" aria-label="NEXORA is thinking"><span class="thinkOrb">✦</span><span class="thinkRing r1"></span><span class="thinkRing r2"></span></div><b>✦ NEXORA</b><span class="thinkingLabel">Thinking…</span></div><div class="thinkingBody"><span>Let me think about that</span><span class="thinkingDots"><i></i><i></i><i></i></span></div>'}async function askAI(){const el=$('#aiInput'),q=el?.value.trim();if(!q)return;el.value='';el.style.height='auto';const log=$('#aiLog'),send=$('#aiSend');if(log){const welcome=log.querySelector('.aiWelcome');if(welcome)welcome.remove();addAIMessage(q,'user');const thinking=document.createElement('div');thinking.className='msg aiMsg thinking';thinking.id='aiThinking';thinking.innerHTML=nexoraThinkingMarkup();log.appendChild(thinking);log.scrollTop=log.scrollHeight}if(send)send.disabled=true;const st=$('#aiStatusText');if(st)st.textContent='Thinking…';const started=Date.now();try{const request=api('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,mode:NEXORA_AI_MODE})});const [d]=await Promise.all([request,new Promise(r=>setTimeout(r,nexoraThinkDelay()))]);const answer=String(d.answer||'I’m here. Tell me more.');const th=$('#aiThinking');if(th){const wrap=document.createElement('div');wrap.className='msg aiMsg';wrap.innerHTML=`<div class="msgHead"><b>✦ NEXORA</b><button class="tinyBtn" onclick="speakAI(this.closest('.msg').querySelector('p').innerText)" title="Speak">🔊</button></div><p>${esc(answer).replace(/\n/g,'<br>')}</p>`;th.replaceWith(wrap)}const chips=$('#aiChips');if(chips)chips.innerHTML=(d.suggestions||[]).slice(0,4).map(s=>`<button class="btn secondary" onclick="aiPrompt(${JSON.stringify(String(s))})">${esc(s)}</button>`).join('');if(log)log.scrollTop=log.scrollHeight;companionReact('happy');checkAIStatus()}catch(e){const th=$('#aiThinking');if(th){th.className='msg aiMsg aiError';th.innerHTML=`<div class="msgHead"><b>✦ NEXORA</b></div><p>I couldn't complete that request. ${esc(e.message||'Please try again.')}</p><button class="btn secondary" onclick="askAI()">Retry</button>`}const st=$('#aiStatusText');if(st)st.textContent='Needs attention';companionReact('error')}finally{if(send)send.disabled=false}}
function companionReact(state){const a=$('#nexoraCompanion');if(!a)return;a.dataset.state=state;clearTimeout(window.__companionTimer);window.__companionTimer=setTimeout(()=>a.dataset.state='idle',1800)}
async function leaderboard(){shell('Leaderboard',`<div class="card"><h3>🏆 Top NEXORA members</h3><p class="muted">Ranked by XP — earned from daily check-ins, posting, and staying active.</p><div id="lbList"></div></div>`);try{const d=await api('/api/leaderboard');const medals=['🥇','🥈','🥉'];$('#lbList').innerHTML=(d.leaderboard||[]).map(u=>`<div class="card between" style="margin-bottom:8px"><div class="author"><div class="avatar">${u.avatar?`<img src="${esc(u.avatar)}">`:esc((u.name||'U')[0])}</div><div><b>${medals[u.rank-1]||('#'+u.rank)} ${esc(u.name)}</b><small>Level ${u.level} · 🔥 ${u.streak}-day streak</small></div></div><span class="pill gold">${u.xp} XP</span></div>`).join('')||'<div class="empty">No ranked members yet.</div>';if(d.myRank)toast(`You're #${d.myRank} with ${d.myXp} XP`)}catch(e){toast(e.message)}}
async function wallet(){shell('Wallet',`<div class="grid2"><div class="card"><small>AVAILABLE BALANCE</small><h2>KSh 0</h2><p class="muted">Marketplace earnings and withdrawals require production payment configuration.</p></div><div class="card"><h3>Payment safety</h3><p>Never share your M-Pesa PIN or OTP. Use only official payment prompts.</p><button class="btn" onclick="nav('settings')">Security settings</button></div></div><div class="card"><h3>Transactions</h3><div id="walletList">Loading…</div></div>`);try{const d=await api('/api/wallet');$('#walletList').innerHTML=(d.wallet?.transactions||[]).map(t=>`<div class="row"><span>${esc(t.description||t.type||'Transaction')}</span><b>KSh ${Number(t.amount||t.total||0).toLocaleString()}</b></div>`).join('')||'<div class="empty">No transactions yet.</div>'}catch(e){toast(e.message)}}
async function orders(){shell('Orders',`<div class="card"><div class="between"><h3>My orders</h3><button class="btn secondary" onclick="orders()">Refresh</button></div><div id="orderList">Loading…</div></div>`);try{const d=await api('/api/orders');$('#orderList').innerHTML=(d.orders||[]).map(o=>`<div class="card"><div class="between"><div><b>${esc(o.item?.title||'Order')}</b><p class="muted">${safeDate(o.createdAt)}</p></div><span class="pill">${esc(o.status)}</span></div><p>Quantity: ${o.qty} • Total: KSh ${Number(o.total||0).toLocaleString()}</p><div class="actions">${o.sellerId===S.user.id&&o.status!=='delivered'&&o.status!=='cancelled'?`<button class="btn" onclick="updateOrder('${o.id}','confirmed')">Confirm</button><button class="btn secondary" onclick="updateOrder('${o.id}','shipped')">Ship</button>`:''}${o.buyerId===S.user.id&&o.status==='shipped'?`<button class="btn" onclick="updateOrder('${o.id}','delivered')">Mark delivered</button>`:''}${!['delivered','cancelled'].includes(o.status)?`<button class="btn danger" onclick="updateOrder('${o.id}','cancelled')">Cancel</button>`:''}</div></div>`).join('')||'<div class="empty">No orders yet.</div>'}catch(e){toast(e.message)}}
async function updateOrder(id,status){try{await api('/api/orders/'+encodeURIComponent(id)+'/status',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});orders();toast('Order updated')}catch(e){toast(e.message)}}
window.addEventListener('error',e=>{if(e?.message)toast('NEXORA error: '+e.message)});window.addEventListener('unhandledrejection',e=>{const m=e?.reason?.message||'Unexpected error';toast('NEXORA error: '+m)});
async function securityCenter(){shell('Security Center',`<div id="securityBox" class="card">Loading…</div>`);try{const d=await api('/api/security');const s=d.security;$('#securityBox').innerHTML=`<h3>Account protection</h3><p>Verification: <b>${s.verified?'Verified':'Not verified'}</b></p><p>Two-factor preference: <b>${s.twoFactor?'Enabled':'Disabled'}</b></p><div class="actions"><button class="btn" onclick="verifyAccount()">${s.verified?'Refresh verification':'Verify locally'}</button><button class="btn secondary" onclick="toggle2FA(${!s.twoFactor})">${s.twoFactor?'Disable 2FA preference':'Enable 2FA preference'}</button><button class="btn danger" onclick="logoutSessions()">Log out all sessions</button></div><h3>Recent logins</h3>${(s.loginEvents||[]).map(x=>`<div class="row"><span>${esc(x.action||'Login')}</span><small>${safeDate(x.createdAt)}</small></div>`).join('')||'<p class="muted">No login activity recorded yet.</p>'}` }catch(e){toast(e.message)}}
async function verifyAccount(){try{await api('/api/security/verify',{method:'POST'});securityCenter();toast('Verification preference enabled')}catch(e){toast(e.message)}}
async function toggle2FA(enabled){try{await api('/api/security/2fa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});securityCenter();toast(enabled?'2FA preference enabled':'2FA preference disabled')}catch(e){toast(e.message)}}
async function logoutSessions(){try{await api('/api/security/logout-sessions',{method:'POST'});toast('Other sessions logged out')}catch(e){toast(e.message)}}

function localList(key){try{return JSON.parse(STORE.get('nexora_'+key)||'[]')}catch{return[]}}
function saveList(key,v){STORE.set('nexora_'+key,JSON.stringify(v))}
function command(){shell('Command Center',`<div class="commandHero"><div class="companionMini">✦</div><div><span class="pill">NEXORA COMMAND CENTER</span><h2>Tell NEXORA what you want to accomplish.</h2><p>Turn a goal into a plan, conversation, checklist or app action.</p></div></div><div class="card"><div class="row"><input id="commandInput" class="input" placeholder="e.g. Help me plan tonight, then create 3 tasks" onkeydown="if(event.key==='Enter')runCommand()"><button class="btn" onclick="runCommand()">Run</button></div><div id="commandResult" class="commandResult"></div></div><div class="grid3"><button class="quick" onclick="runCommandText('Plan my day')">🗓 Plan my day</button><button class="quick" onclick="runCommandText('Give me ideas for making money online')">💡 Give me ideas</button><button class="quick" onclick="runCommandText('I want to meet new people')">🤝 Help me connect</button><button class="quick" onclick="runCommandText('Create a 30 minute focus session')">⏱ Focus session</button><button class="quick" onclick="runCommandText('Start a positive conversation with me')">💬 Talk with me</button><button class="quick" onclick="runCommandText('Give me a decision framework')">⚖️ Help me decide</button></div>`)}
function runCommandText(t){if($('#commandInput')){$('#commandInput').value=t;runCommand()}}
async function runCommand(){const q=$('#commandInput')?.value.trim();if(!q)return;const out=$('#commandResult');if(out)out.innerHTML='<div class="commandLoading">✦ NEXORA is thinking…</div>';try{const d=await api('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'[Command Center] '+q})});if(out)out.innerHTML=`<div class="commandAnswer"><b>✦ NEXORA</b><p>${esc(d.answer||'Done.').replace(/\n/g,'<br>')}</p><div class="actions">${(d.suggestions||[]).map(x=>`<button class="btn secondary" onclick="runCommandText('${String(x).replace(/'/g,"\\'")}')">${esc(x)}</button>`).join('')}</div></div>`;companionReact('happy')}catch(e){if(out)out.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function socialConnect(){shell('Connect',`<div class="card connectHero"><div class="between"><div><span class="pill">REAL PEOPLE</span><h2>Connect beyond the feed.</h2><p>Find people, start conversations, share a mood and build genuine connections.</p></div><div class="presenceDot">● Online</div></div></div><div class="card"><h3>Your social status</h3><div class="actions"><button class="btn secondary" onclick="setPresence('Available')">🟢 Available</button><button class="btn secondary" onclick="setPresence('Busy')">🔴 Busy</button><button class="btn secondary" onclick="setPresence('Chilling')">🟣 Chilling</button><button class="btn secondary" onclick="setPresence('Away')">🟡 Away</button></div><p id="presenceText" class="muted"></p></div><div class="card"><h3>Conversation starters</h3><div class="grid3"><button class="quick" onclick="starter('What are you working on lately?')">What are you working on?</button><button class="quick" onclick="starter('What is something you are excited about?')">What excites you?</button><button class="quick" onclick="starter('Tell me something interesting')">Tell me something interesting</button></div></div><div class="card"><h3>Find people</h3><input id="peopleSearch" class="input" placeholder="Search members…" oninput="searchPeople()"><div id="peopleResults"></div></div>`);searchPeople();const p=STORE.get('nexora_presence')||'Available';if($('#presenceText'))$('#presenceText').textContent='Status: '+p}
function setPresence(p){STORE.set('nexora_presence',p);if($('#presenceText'))$('#presenceText').textContent='Status: '+p;toast('Status updated to '+p)}
function starter(t){nav('messages');setTimeout(()=>toast('Starter: '+t),150)}
async function searchPeople(){const q=$('#peopleSearch')?.value||'';try{const d=await api('/api/users?q='+encodeURIComponent(q));$('#peopleResults').innerHTML=(d.users||[]).slice(0,12).map(u=>`<div class="personRow"><div class="avatar">${u.avatar?`<img src="${esc(u.avatar)}">`:esc((u.name||'U')[0])}</div><div><b>${esc(u.name)}</b><small>${esc(u.bio||'NEXORA member')}</small></div><div class="actions"><button class="btn secondary" onclick="openDirect('${u.id}',decodeURIComponent('${encodeURIComponent(u.name)}'))">Message</button></div></div>`).join('')||'<div class="empty">No people found.</div>'}catch(e){toast(e.message)}}
function studio(){shell('Creative Studio',`<div class="card studioHero"><span class="pill">CREATE SOMETHING</span><h2>Ideas in. Something useful out.</h2><p>Use NEXORA for writing, social posts, plans, captions and creative concepts.</p></div><div class="grid2"><div class="card"><h3>✍️ Writing assistant</h3><textarea id="studioText" class="input" style="min-height:150px" placeholder="Paste rough thoughts or describe what you need…"></textarea><div class="actions"><button class="btn" onclick="studioGenerate('polish')">Polish it</button><button class="btn secondary" onclick="studioGenerate('social')">Make social post</button><button class="btn secondary" onclick="studioGenerate('short')">Make concise</button></div></div><div class="card"><h3>💡 Idea generator</h3><input id="ideaTopic" class="input" placeholder="Topic or goal"><button class="btn" onclick="studioGenerate('ideas')">Generate ideas</button><div id="studioOutput" class="studioOutput"></div></div></div>`)}
async function studioGenerate(mode){const text=$('#studioText')?.value||$('#ideaTopic')?.value||'';if(!text.trim()){toast('Add a topic or text first');return}const out=$('#studioOutput');if(out)out.innerHTML='✦ Creating…';const prompts={polish:'Polish this naturally while keeping my voice: ',social:'Turn this into a friendly social post: ',short:'Make this concise and clear: ',ideas:'Give me 7 practical creative ideas for: '};try{const d=await api('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompts[mode]+text})});if(out)out.innerHTML=`<div class="resultText">${esc(d.answer||'No result').replace(/\n/g,'<br>')}</div><button class="btn secondary" onclick="copyText(this.previousElementSibling.innerText)">Copy</button>`}catch(e){if(out)out.textContent=e.message}}
function copyText(t){navigator.clipboard?.writeText(t).then(()=>toast('Copied')).catch(()=>toast('Copy is unavailable'))}
function projects(){const list=localList('projects');shell('Projects',`<div class="card"><div class="between"><div><h3>Your workspaces</h3><p class="muted">Keep conversations, goals and notes organized.</p></div><button class="btn" onclick="newProject()">＋ New project</button></div><div id="projectList">${list.map((x,i)=>`<div class="projectRow"><div><b>${esc(x.name)}</b><small>${esc(x.desc||'Personal workspace')}</small></div><button class="btn danger" onclick="deleteProject(${i})">Delete</button></div>`).join('')||'<div class="empty">No projects yet. Create your first workspace.</div>'}</div></div>`)}
function newProject(){const name=prompt('Project name');if(!name?.trim())return;const list=localList('projects');list.unshift({name:name.trim().slice(0,80),desc:'Created in NEXORA',createdAt:Date.now()});saveList('projects',list);projects();toast('Project created')}
function deleteProject(i){const list=localList('projects');list.splice(i,1);saveList('projects',list);projects()}
function focus(){shell('Focus Mode',`<div class="focusCard"><div class="companionMini">✦</div><span class="pill">FOCUS</span><h2 id="focusTimer">25:00</h2><p class="muted">A simple distraction-free session. Your companion stays quietly with you.</p><div class="actions"><button class="btn" onclick="focusStart()">Start</button><button class="btn secondary" onclick="focusPause()">Pause</button><button class="btn secondary" onclick="focusReset()">Reset</button></div><input id="focusGoal" class="input" placeholder="What are you focusing on?"></div>`)}
let focusSeconds=1500,focusInt=null;function focusRender(){const e=$('#focusTimer');if(e)e.textContent=String(Math.floor(focusSeconds/60)).padStart(2,'0')+':'+String(focusSeconds%60).padStart(2,'0')}
function focusStart(){if(focusInt)return;focusInt=setInterval(()=>{if(focusSeconds>0){focusSeconds--;focusRender()}else{focusPause();toast('Focus session complete 🎉');celebrate()}},1000);toast('Focus started')}
function focusPause(){clearInterval(focusInt);focusInt=null}
function focusReset(){focusPause();focusSeconds=1500;focusRender()}
function mountCompanion(){if($('#nexoraCompanion'))return;const a=document.createElement('button');a.id='nexoraCompanion';a.className='nexoraCompanion';a.dataset.state='idle';a.title='Talk to NEXORA';a.innerHTML='<span class="companionSpark">✦</span><span class="companionFace">◉</span><span class="companionPulse"></span>';a.onclick=()=>{nav('ai');setTimeout(()=>$('#aiInput')?.focus(),80)};document.body.appendChild(a)}
function render(){if(!S.token)return auth();document.body.dataset.theme=S.theme;mountCompanion();const f={home,dashboard,explore,opportunities,marketplace,communities,messages,stories,events,education,notifications,saved,applications,profile,settings,safety,help,admin,ai,wallet,orders,analytics,leaderboard,command,connect:socialConnect,studio,projects,focus};(f[S.page]||home)()}
